   100→  /** Clear the crypto store directories to fix device ID mismatches */
   101→  private static async clearCryptoStore() {
   102→    try {
   103→      const dataExists = await RNFS.exists(dataPath);
   104→      const cacheExists = await RNFS.exists(cachePath);
   105→
   106→      if (dataExists) {
   107→        await RNFS.unlink(dataPath);
   108→        console.log("Cleared crypto data store");
   109→      }
   110→
   111→      if (cacheExists) {
   112→        await RNFS.unlink(cachePath);
   113→        console.log("Cleared crypto cache store");
   114→      }
   115→    } catch (error) {
   116→      console.warn("Failed to clear crypto store:", error);
   117→    }
   118→  }
