   141→  /** Lightweight session restore for background operations (e.g., push notification decryption)
   142→   * Only initializes the client and encryption, does NOT start sync service. */
   143→  public static restoreSessionForBackground = async (): Promise<boolean> => {
   144→    try {
   145→      // Already initialized with notification client
   146→      if (this.instance && this.notificationClient) return true;
   147→
   148→      const credentials = MatrixStorage.getLoginCredentials();
   149→      if (!credentials) return false;
   150→
   151→      await this.initialize(credentials.baseUrl);
   152→
   153→      if (!this.instance) throw new Error("Failed to initialize client");
   154→
   155→      const client: ClientInterface = this.instance;
   156→
   157→      await client.restoreSession({
   158→        accessToken: credentials.accessToken,
   159→        refreshToken: credentials.refreshToken,
   160→        userId: credentials.userId,
   161→        deviceId: credentials.deviceId,
   162→        homeserverUrl: credentials.baseUrl,
   163→        oidcData: undefined,
   164→        slidingSyncVersion: SlidingSyncVersion.Native,
   165→      });
   166→
   167→      // Wait for E2EE to be ready (required for decryption)
   168→      await client.encryption().waitForE2eeInitializationTasks();
   169→
   170→      // Create notification client for background decryption
   171→      // MultipleProcesses mode is for when main app might also be running
   172→      this.notificationClient = await client.notificationClient(
   173→        new NotificationProcessSetup.MultipleProcesses(),
   174→      );
   175→
   176→      return true;
   177→    } catch (error) {
   178→      console.error("[Background] Failed to restore session:", error);
   179→      return false;
   180→    }
   181→  };
