   280→      MatrixStorage.clearLoginCredentials();
   281→      await this.clearCryptoStore();
   282→
   283→      // Reset the instance so it can be recreated fresh
   284→      this.instance = null;
   285→      this.syncService = null;
   286→
   287→      // Clear atoms
   288→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
