   295→  /** Call this after logging in to create a new client instance with the provided account.  */
   296→  public static setup = async (params: Session) => {
   297→    // Clear any existing crypto store to prevent device ID mismatches
   298→    await this.clearCryptoStore();
   299→
   300→    // Stop and clear existing instances
   301→    if (this.syncService) await this.syncService.stop();
   302→    this.instance = null;
   303→    this.syncService = null;
   304→
   305→    // Save credentials for future auto-login
   306→    MatrixStorage.saveLoginCredentials({
   307→      accessToken: params.accessToken,
   308→      refreshToken: params.refreshToken,
   309→      userId: params.userId,
   310→      deviceId: params.deviceId,
   311→      baseUrl: params.homeserverUrl,
   312→    });
   313→
   314→    // Create a fresh client instance and configure it with the session + sliding sync
   315→    await this.initialize(params.homeserverUrl);
   316→
   317→    if (!this.instance) throw new Error("Failed to initialize client");
   318→
   319→    // Use local variable to help TypeScript with type narrowing
   320→    const client: ClientInterface = this.instance;
   321→
   322→    await client.restoreSession({
   323→      accessToken: params.accessToken,
   324→      refreshToken: params.refreshToken,
   325→      userId: params.userId,
   326→      deviceId: params.deviceId,
   327→      homeserverUrl: params.homeserverUrl,
   328→      oidcData: undefined,
   329→      slidingSyncVersion: SlidingSyncVersion.Native,
   330→    });
   331→
   332→    // Verify the session is valid by making a server request
   333→    // Use the params.userId since client.userId() might not be populated yet
   334→    try {
   335→      this.profile = await client.getProfile(params.userId);
   336→    } catch (error) {
   337→      console.warn("Session validation failed:", error);
   338→      throw new Error("Session is invalid or expired");
   339→    }
   340→
   341→    this.syncService = await client.syncService().finish();
   342→
   343→    if (!this.syncService) throw new Error("Failed to initialize sync service");
   344→
   345→    await this.syncService.start();
   346→    await client.encryption().waitForE2eeInitializationTasks();
   347→
   348→    // Check if we need to bootstrap cross-signing or enable backups
   349→    try {
   350→      const encryption = client.encryption();
   351→      const backupExists = await encryption.backupExistsOnServer();
   352→      console.log("Backup exists on server:", backupExists);
   353→      console.log(
   354→        "Current verification state:",
   355→        encryption.verificationState(),
   356→      );
   357→
   358→      // If no backup exists and we're the only device, we might need to set one up
   359→      const isLastDevice = await encryption.isLastDevice();
   360→      console.log("Is last device:", isLastDevice);
   361→
   362→      if (!backupExists) {
   363→        console.log("Enabling backups for cross-signing...");
   364→        await encryption.enableBackups();
   365→      }
   366→
   367→      // Update atoms so providers can react to the initialized service
   368→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
   369→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
   370→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
   371→    } catch (error) {
   372→      console.warn("Failed to check backup/verification status:", error);
   373→    }
   374→  };
