   459→  /** Manually refresh the room list and update the atom */
   460→  public static refreshRoomList = async () => {
   461→    if (!this.instance) return;
   462→
   463→    try {
   464→      const roomsArray = this.getRooms();
   465→
   466→      const sortedRooms = await Promise.all(
   467→        roomsArray.map(async (room) => ({
   468→          room,
   469→          timestamp: (await room.latestEvent())?.timestamp || 0,
   470→        })),
   471→      );
   472→
   473→      const filteredAndSortedRooms = sortedRooms
   474→        .filter(({ room }) => {
   475→          const membership = room.membership();
   476→
   477→          return (
   478→            membership !== Membership.Banned &&
   479→            membership !== Membership.Left &&
   480→            membership !== Membership.Knocked
   481→          );
   482→        })
   483→        .sort((a, b) => {
   484→          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
   485→          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
   486→          if (aInvited !== bInvited) return bInvited - aInvited;
   487→
   488→          return Number(b.timestamp) - Number(a.timestamp);
   489→        });
   490→
   491→      MatrixJotaiStore.set(
   492→        MatrixAtoms.roomList,
   493→        filteredAndSortedRooms.map(({ room }) => room),
   494→      );
   495→    } catch (error) {
   496→      console.error("Failed to refresh room list:", error);
   497→    }
   498→  };
