   500→  /** Log in with a username and password.
   501→   * This will return the login response directly that you have to use to set up the service. */
   502→  public static login = async ({
   503→    username,
   504→    password,
   505→  }: LoginWithUsernameAndPasswordData) => {
   506→    if (!this.instance) throw new Error("Failed to initialize client");
   507→    await this.instance.login(username, password, undefined, undefined);
   508→    const session = this.instance.session();
   509→    console.log(
   510→      this.instance.encryption().verificationState(),
   511→      "verificationState",
   512→    );
   513→
   514→    // After login, we need to recreate the client with sliding sync configured
   515→    // The login call above authenticated us and gave us session data
   516→    // Now we destroy this instance so we can rebuild with proper sliding sync
   517→    this.instance = null;
   518→
   519→    return session;
   520→  };
