   542→  public static deactivateAccount = async (password: string) => {
   543→    if (!this.instance) throw new Error("Client not initialized");
   544→
   545→    try {
   546→      // First request with undefined auth_data (will always fail per UIA spec)
   547→      try {
   548→        await this.instance.deactivateAccount(undefined, true);
   549→      } catch {
   550→        // Expected to fail
   551→      }
   552→
   553→      console.log(this.instance.userId(), "userId");
   554→      const userId = this.instance.userId();
   555→      if (!userId) throw new Error("User ID not found");
   556→
   557→      const authData = new AuthData.Password({
   558→        passwordDetails: AuthDataPasswordDetails.create({
   559→          identifier: userId,
   560→          password,
   561→        }),
   562→      });
   563→
   564→      // Step 4: Second request with auth data
   565→      await this.instance.deactivateAccount(authData, true);
