  1057→      const profiles = await Promise.allSettled(profilePromises);
  1058→      return profiles
  1059→        .filter((p) => p.status === "fulfilled")
  1060→        .map((p) => p.value)
  1061→        .filter((p) => p !== undefined);
  1062→    } catch (error) {
  1063→      console.error("Failed to get read receipt users:", error);
  1064→      return [];
