  1694→
  1695→    const pusherData = {
  1696→      pushkey: pushToken,
  1697→      kind: "http",
  1698→      app_id: APP_ID,
  1699→      app_display_name: "Cloak",
  1700→      device_display_name: session.deviceId || "Mobile Device",
  1701→      profile_tag: "", // Optional: for multiple pushers per device
  1702→      lang: "en",
  1703→      data: {
