  1717→          body: JSON.stringify(pusherData),
  1718→        },
  1719→      );
  1720→
  1721→      if (!response.ok) {
  1722→        console.log("Failed to set pusher:", response);
  1723→        const errorText = await response.text();
  1724→        throw new Error(
  1725→          `Failed to set pusher: ${response.status} - ${errorText}`,
  1726→        );
  1727→      }
  1728→
  1729→      return true;
  1730→    } catch (error) {
  1731→      console.error("Failed to register pusher:", error);
  1732→      throw error;
  1733→    }
  1734→  };
  1735→
  1736→  /** Remove a pusher from the homeserver */
  1737→  public static removePusher = async (pushToken: string) => {
  1738→    if (!this.instance) throw new Error("Client not initialized");
  1739→
  1740→    const session = this.instance.session();
  1741→    if (!session) throw new Error("No active session");
  1742→
  1743→    const pusherData = {
  1744→      pushkey: pushToken,
  1745→      kind: null, // Setting kind to null removes the pusher
  1746→      app_id: APP_ID,
  1747→    };
  1748→
  1749→    try {
  1750→      const response = await fetch(
  1751→        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_SET}`,
  1752→        {
  1753→          method: "POST",
  1754→          headers: {
  1755→            "Content-Type": "application/json",
  1756→            Authorization: `Bearer ${session.accessToken}`,
  1757→          },
  1758→          body: JSON.stringify(pusherData),
  1759→        },
  1760→      );
  1761→
  1762→      if (!response.ok) {
  1763→        const errorText = await response.text();
  1764→        throw new Error(
  1765→          `Failed to remove pusher: ${response.status} - ${errorText}`,
  1766→        );
  1767→      }
  1768→
  1769→      console.log("Pusher removed successfully from homeserver");
  1770→      return true;
  1771→    } catch (error) {
  1772→      console.error("Failed to remove pusher:", error);
  1773→      throw error;
  1774→    }
  1775→  };
