  1777→  // PINNED MESSAGES METHODS
  1778→
  1779→  /** Get the list of pinned event IDs for a room */
  1780→  public static getPinnedEventIds = async (
  1781→    roomId: string,
  1782→  ): Promise<string[]> => {
  1783→    if (!this.instance) throw new Error("Client not initialized");
  1784→
  1785→    const room = this.instance.getRoom(roomId);
  1786→    if (!room) throw new Error("Room not found");
  1787→
  1788→    const roomInfo = await room.roomInfo();
  1789→    return roomInfo.pinnedEventIds || [];
  1790→  };
  1791→
  1792→  /** Pin a message in a room */
  1793→  public static pinMessage = async (
  1794→    roomId: string,
  1795→    eventId: string,
  1796→  ): Promise<void> => {
  1797→    if (!this.instance) throw new Error("Client not initialized");
  1798→
  1799→    const room = this.instance.getRoom(roomId);
  1800→    if (!room) throw new Error("Room not found");
  1801→
  1802→    const timeline = await room.timeline();
  1803→    if (!timeline) throw new Error("Timeline not found");
  1804→
  1805→    await timeline.pinEvent(eventId);
  1806→  };
  1807→
  1808→  /** Unpin a message in a room */
  1809→  public static unpinMessage = async (
  1810→    roomId: string,
  1811→    eventId: string,
  1812→  ): Promise<void> => {
  1813→    if (!this.instance) throw new Error("Client not initialized");
  1814→
  1815→    const room = this.instance.getRoom(roomId);
  1816→    if (!room) throw new Error("Room not found");
  1817→
  1818→    const timeline = await room.timeline();
  1819→    if (!timeline) throw new Error("Timeline not found");
  1820→
  1821→    await timeline.unpinEvent(eventId);
  1822→  };
  1823→
  1824→  /** Check if a message is pinned */
